import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 실행예산은 승인·마감 상태인 월별 금액만 배정액에 넣는다.
// 가정: 승인된 예산조정은 기간 구분 없이 전부 반영한다 (추경예산·예비비는 출처 과목에 더하고, 전용·이용은 출처에서 빼고 상대 과목에 더한다).
// 가정: 집행액은 같은 프로젝트·예산과목의 승인·완료 결의서 금액을 통제 주기 기간(결의서 생성일 기준)으로 합한다.

function idOf(value: unknown, label: string): string {
  const text = String(value ?? '');
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr03210Controller {
  @Get('/budget-controls')
  async getBudgetControl(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const data = checks.queryOf(req.query);
    const projectId = idOf(data['projectId'], '프로젝트');
    const budgetAccountId = idOf(data['budgetAccountId'], '예산과목');
    const rawDate = data['baseDate'];
    let baseDate: string | null = null;
    if (rawDate !== undefined && rawDate !== null && String(rawDate) !== '') {
      baseDate = String(rawDate);
      if (!/^\d{4}-\d{2}-\d{2}$/.test(baseDate)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '기준 일자 형식이 올바르지 않습니다.');
      }
    }
    const rawAmount = data['requestAmount'];
    let requestAmount = 0;
    if (rawAmount !== undefined && rawAmount !== null && String(rawAmount) !== '') {
      requestAmount = Number(rawAmount);
      if (!Number.isFinite(requestAmount) || requestAmount < 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '집행 요청 금액은 0 이상의 숫자여야 합니다.');
      }
    }
    return transaction(async (db) => {
      const accounts = await db.query(
        `SELECT control_cycle AS "controlCycle"
           FROM budget_account
          WHERE budget_account_id = CAST(:budgetAccountId AS bigint)`,
        { budgetAccountId },
      );
      const projects = await db.query(
        `SELECT project_id AS "projectId"
           FROM project
          WHERE project_id = CAST(:projectId AS bigint)`,
        { projectId },
      );
      if (accounts.length === 0 || projects.length === 0) {
        throw new ApiError(404, 'BUDGET_BASIS_NOT_FOUND', '예산과목 또는 실행예산이 없습니다. 기준정보를 확인해 주세요.');
      }
      const controlCycle = String(accounts[0]['controlCycle']);
      const basis = await db.query(
        `SELECT CAST(EXTRACT(YEAR FROM d) AS integer) AS "year",
                CAST(EXTRACT(MONTH FROM d) AS integer) AS "month"
           FROM (SELECT COALESCE(CAST(:baseDate AS date), CURRENT_DATE) AS d) t`,
        { baseDate },
      );
      const year = Number(basis[0]['year']);
      const month = Number(basis[0]['month']);
      let fromMonth = 1;
      let toMonth = 12;
      if (controlCycle === '월') {
        fromMonth = month;
        toMonth = month;
      } else if (controlCycle === '분기') {
        fromMonth = Math.floor((month - 1) / 3) * 3 + 1;
        toMonth = fromMonth + 2;
      }
      const period = { year, fromMonth, toMonth };
      const executions = await db.query(
        `SELECT COUNT(*) AS "count",
                COALESCE(SUM(e.execution_amount), 0) AS "amount"
           FROM budget_execution e
           JOIN budget_main m ON m.budget_main_id = e.budget_main_id
          WHERE m.project_id = CAST(:projectId AS bigint)
            AND m.budget_account_id = CAST(:budgetAccountId AS bigint)
            AND m.fiscal_year = CAST(:year AS integer)
            AND e.execution_month BETWEEN CAST(:fromMonth AS integer) AND CAST(:toMonth AS integer)
            AND e.approval_status IN ('승인', '마감')`,
        { projectId, budgetAccountId, ...period },
      );
      if (Number(executions[0]['count']) === 0) {
        throw new ApiError(404, 'BUDGET_BASIS_NOT_FOUND', '예산과목 또는 실행예산이 없습니다. 기준정보를 확인해 주세요.');
      }
      const adjustments = await db.query(
        `SELECT COALESCE(SUM(CASE
                  WHEN budget_account_id = CAST(:budgetAccountId AS bigint)
                       AND adjustment_type IN ('추경예산', '예비비') THEN adjustment_amount
                  WHEN target_budget_account_id = CAST(:budgetAccountId AS bigint) THEN adjustment_amount
                  WHEN budget_account_id = CAST(:budgetAccountId AS bigint)
                       AND adjustment_type IN ('전용', '이용') THEN -adjustment_amount
                  ELSE 0 END), 0) AS "amount"
           FROM budget_adjustment
          WHERE project_id = CAST(:projectId AS bigint)
            AND approval_status = '승인'
            AND (budget_account_id = CAST(:budgetAccountId AS bigint)
                 OR target_budget_account_id = CAST(:budgetAccountId AS bigint))`,
        { projectId, budgetAccountId },
      );
      const executed = await db.query(
        `SELECT COALESCE(SUM(resolution_amount), 0) AS "amount"
           FROM expense_resolution
          WHERE project_id = CAST(:projectId AS bigint)
            AND budget_account_id = CAST(:budgetAccountId AS bigint)
            AND status IN ('승인', '완료')
            AND EXTRACT(YEAR FROM created_at) = CAST(:year AS integer)
            AND EXTRACT(MONTH FROM created_at) BETWEEN CAST(:fromMonth AS integer) AND CAST(:toMonth AS integer)`,
        { projectId, budgetAccountId, ...period },
      );
      const allocatedAmount = Number(executions[0]['amount']) + Number(adjustments[0]['amount']);
      const executedAmount = Number(executed[0]['amount']);
      const balanceAmount = allocatedAmount - executedAmount;
      const executable = requestAmount <= balanceAmount;
      if (!executable) {
        throw new ApiError(422, 'BUDGET_BALANCE_EXCEEDED', '요청 금액이 잔액을 초과하여 집행할 수 없습니다.');
      }
      return {
        allocatedAmount,
        executedAmount,
        balanceAmount,
        controlCycle,
        executable,
      };
    });
  }
}

